int __fastcall SmokeTextureMemoryQuery(
    int flags,
    int *totalBytes,
    int *freeBytes
) {
    ++g_smokeTextureMemoryQueryCalls;
    g_smokeLastTextureMemoryQueryFlags = flags;
    *totalBytes = 0x1000;
    *freeBytes = 0x400;
    return 0;
}

int __fastcall SmokeDeviceMemoryQuery(
    int flags,
    int *totalBytes,
    int *freeBytes
) {
    ++g_smokeDeviceMemoryQueryCalls;
    g_smokeLastDeviceMemoryQueryFlags = flags;
    *totalBytes = 0x2000;
    *freeBytes = 0x800;
    return 0;
}

bool SmokePlayerFloatNear(float actual, float expected) {
    const float delta = actual - expected;
    return delta < 0.0001f && delta > -0.0001f;
}

bool SmokePlayerVec3Equals(const zVec3 &value, const zVec3 &expected) {
    return value.x == expected.x && value.y == expected.y && value.z == expected.z;
}

void MakeSmokeAinetReaderStringNode(zReader::Node &node, const char *value) {
    node.type = zReader::ZRDR_NODE_STRING;
    node.value.str = const_cast<char *>(value);
}

void MakeSmokeAinetReaderIntNode(zReader::Node &node, int value) {
    node.type = zReader::ZRDR_NODE_INT;
    node.value.i32 = value;
}

void MakeSmokeAinetReaderFloatNode(zReader::Node &node, float value) {
    node.type = zReader::ZRDR_NODE_FLOAT;
    node.value.f32 = value;
}

void MakeSmokeAinetReaderArrayNode(
    zReader::Node &node,
    zReader::Node *payload,
    int count
) {
    payload[0].type = zReader::ZRDR_NODE_INT;
    payload[0].value.i32 = count;
    node.type = zReader::ZRDR_NODE_ARRAY;
    node.value.nodes = payload;
}

