            g_zVideo_CachedClientRectScreen.top == 8 &&
            g_zVideo_CachedClientRectScreen.right == 9 &&
            g_zVideo_CachedClientRectScreen.bottom == 10;

        g_zVideo_ActiveRendererPath = 1;
